async function findUsers(o){return $.ajax({url:"/api/contact/user?search="+o,type:"GET",dataType:"json",success:function(n){return n}})}$("#nama").on("keyup",async function(){let o=$(this).val(),t=await findUsers(o);if(t.data.length==1){let n=t.data[0];$("#username").val(n.nama),$("#nik").val(n.fullnik),$("#departemen").val(n.departemen),$("#email").val(n.email),$("#noHp").val(n.noHp),$("#url").val(n.url),$("#tanggal").prop("disabled",!1)}});async function attendence(o){}$("#tanggal").on("change",function(){let o=$(this).val(),t=$("#nik").val();$.ajax({url:`/api/presensi/riwayat/${t}?periode=${o}`,method:"GET"}).then(n=>{let a=n.data;$("#jamMasuk").val("--:--:--"),$("#jamKeluar").val("--:--:--"),$("#jamMasuk").prop("disabled",!1),$("#jamKeluar").prop("disabled",!1),$("#locatonIn").find("option").remove().end(),$("#locatonOut").find("option").remove().end(),a.length>0?(a[0].cekIn==null?($("#locatonIn").append('<option value="LOBBY">LOBBY</option>'),$("#locatonIn").append('<option value="LOBBY IGD">LOBBY IGD</option>'),$("#locatonIn").append('<option value="KELAS 1">KELAS 1</option>'),$("#locatonIn").append('<option value="BANGSAL BEDAH">BANGSAL BEDAH</option>'),$("#locatonIn").append('<option value="IBS">IBS</option>'),$("#locatonIn").append('<option value="Dinas Luar">Dinas Luar</option>')):($("#jamMasuk").val(a[0].cekIn),$("#locatonIn").append(`<option selected value="${a[0].loactionIn}">${a[0].loactionIn}</option>`)),a[0].cekOut==null?($("#locatonOut").append('<option value="LOBBY">LOBBY</option>'),$("#locatonOut").append('<option value="LOBBY IGD">LOBBY IGD</option>'),$("#locatonOut").append('<option value="KELAS 1">KELAS 1</option>'),$("#locatonOut").append('<option value="BANGSAL BEDAH">BANGSAL BEDAH</option>'),$("#locatonOut").append('<option value="IBS">IBS</option>'),$("#locatonOut").append('<option value="Dinas Luar">Dinas Luar</option>')):($("#jamKeluar").val(a[0].cekOut),$("#locatonOut").append(`<option selected value="${a[0].loactionOut}">${a[0].loactionOut}</option>`))):($("#locatonIn").append('<option value="LOBBY">LOBBY</option>'),$("#locatonIn").append('<option value="LOBBY IGD">LOBBY IGD</option>'),$("#locatonIn").append('<option value="KELAS 1">KELAS 1</option>'),$("#locatonIn").append('<option value="BANGSAL BEDAH">BANGSAL BEDAH</option>'),$("#locatonIn").append('<option value="IBS">IBS</option>'),$("#locatonIn").append('<option value="Dinas Luar">Dinas Luar</option>'),$("#locatonOut").append('<option value="LOBBY">LOBBY</option>'),$("#locatonOut").append('<option value="LOBBY IGD">LOBBY IGD</option>'),$("#locatonOut").append('<option value="KELAS 1">KELAS 1</option>'),$("#locatonOut").append('<option value="BANGSAL BEDAH">BANGSAL BEDAH</option>'),$("#locatonOut").append('<option value="IBS">IBS</option>'),$("#locatonOut").append('<option value="Dinas Luar">Dinas Luar</option>'))}).catch(n=>{console.error(n)})}),document.getElementById("formPresensi").addEventListener("submit",o=>{o.preventDefault();let t=document.getElementById("nik").value,n=document.getElementById("tanggal").value,a=document.getElementById("jamMasuk").value,l=document.getElementById("jamKeluar").value,p=document.getElementById("locatonIn").value,i=document.getElementById("locatonOut").value,u=JSON.stringify({nik:t,tanggal:n,jamMasuk:a,jamKeluar:l,locatonIn:p,locatonOut:i});fetch("/api/presensi/backdate/"+t,{headers:{"Content-Type":"application/json"},method:"POST",body:u}).then(e=>e.json()).then(e=>e.error?Swal.fire({title:"Peringatan",text:e.message,icon:"warning"}):Swal.fire({title:"Berhasil",text:e.message,icon:"success"})).catch(e=>{console.error(e)})});
